import { agents, getPolicy, getWorkflow, users } from "@/lib/config/catalog";
import type { SessionChannel } from "@/lib/domain/types";
import { SimulationHarness } from "@/lib/simulation/harness";
import type { SessionRuntime } from "./session-runtime";

/**
 * Seeds the POC runtime with history and a few in-flight sessions. Every
 * session is generated by driving the real orchestrator with the simulated
 * customer, so analytics, audit and costs are computed from genuine session
 * records rather than hard-coded figures. Sessions are tagged by scenario and
 * clearly flagged as simulated in the UI.
 */

function mulberry32(seed: number) {
  return () => {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function pick<T>(rand: () => number, weighted: [T, number][]): T {
  const total = weighted.reduce((s, [, w]) => s + w, 0);
  let r = rand() * total;
  for (const [v, w] of weighted) {
    r -= w;
    if (r <= 0) return v;
  }
  return weighted[weighted.length - 1][0];
}

const SCENARIO_WEIGHTS: [string, number][] = [
  ["power_cycle_fix", 30],
  ["wan_down", 24],
  ["loose_cable", 12],
  ["glare_then_clear", 12],
  ["wrong_device", 8],
  ["persistently_unclear", 7],
  ["vision_outage", 3],
];

const CHANNELS: [SessionChannel, number][] = [
  ["sms", 45],
  ["secure_link", 25],
  ["contact_centre", 20],
  ["qr", 5],
  ["website", 5],
];

const ISSUES = [
  "My internet isn't working. The router lights look different.",
  "Broadband keeps dropping out since this morning",
  "No internet on any device, the Wi-Fi is there but nothing loads",
  "The internet light on my router is off",
  "My broadband's down and I work from home",
];

export function seedSessions(rt: SessionRuntime, now = Date.now()) {
  const rand = mulberry32(20261011);
  const workflow = getWorkflow("wf_router_v3")!;
  const policy = getPolicy(workflow.policyId)!;
  const agent = agents.find((a) => a.id === "agt_northline_router")!;
  const humanAgents = users.filter((u) => u.tenantId === "tnt_northline" && u.role === "agent");
  let ref = 11800;

  const make = (scenario: string, startAt: number) => {
    ref += 1;
    return new SimulationHarness(
      { workflow, policy, agent },
      {
        id: `ses_${ref.toString(36)}${Math.floor(rand() * 1e6).toString(36)}`,
        reference: `VA-${ref}`,
        tenantId: workflow.tenantId,
        scenario,
        channel: pick(rand, CHANNELS),
        customerLabel: `Account ••${String(1000 + Math.floor(rand() * 9000))}`,
        startAt,
      },
    );
  };

  // --- History: past 14 days ------------------------------------------------
  const DAYS = 14;
  for (let d = DAYS; d >= 1; d--) {
    const perDay = 4 + Math.floor(rand() * 5) + (d % 7 === 1 || d % 7 === 2 ? -2 : 0);
    for (let i = 0; i < perDay; i++) {
      const day = new Date(now - d * 86_400_000);
      day.setUTCHours(8 + Math.floor(rand() * 12), Math.floor(rand() * 60), Math.floor(rand() * 60), 0);
      const h = make(pick(rand, SCENARIO_WEIGHTS), day.getTime());
      const roll = rand();
      const agentUser = humanAgents[Math.floor(rand() * humanAgents.length)];
      const actor = { type: "human_agent" as const, id: agentUser.id, name: agentUser.name };

      if (roll < 0.05) {
        // Customer drops out early.
        h.runCustomer({ issue: ISSUES[Math.floor(rand() * ISSUES.length)], maxTurns: 3 });
        h.advance(20 + rand() * 60);
        h.send({ type: "session.end", reason: "Customer closed the page" });
      } else {
        h.runCustomer({ issue: ISSUES[Math.floor(rand() * ISSUES.length)], maxTurns: roll < 0.12 ? 3 : 30 });
        if (roll < 0.12 && h.state.session.status === "active") {
          h.advance(10);
          h.send({ type: "customer.utterance", text: "Can I speak to a real person please?", confidence: 0.92 });
        }
        if (h.state.customerState === "resolved") {
          h.advance(8 + rand() * 20);
          h.send({ type: "session.end" });
        } else if (h.state.escalation) {
          h.advance(25 + rand() * 200);
          h.send({ type: "human.join" }, actor);
          h.send({ type: "human.take_over" }, actor);
          h.advance(30 + rand() * 60);
          const reason = h.state.escalation?.reason;
          if (reason === "low_visual_confidence" || reason === "repeated_capture_failure") {
            h.send({ type: "human.request_capture", prompt: "Could you tilt the phone slightly so the light from the window isn't on the router?" }, actor);
            h.advance(15);
            h.capture();
            h.advance(30);
            const obs = h.state.observations.at(-2);
            if (obs) h.send({ type: "human.review_observation", observationId: obs.id, verdict: "confirmed" }, actor);
            h.send({ type: "human.note", text: "Glare from window. Confirmed internet light off on manual view." }, actor);
          }
          if (h.state.workflow.toolFacts["line_test.status"] === "fault_detected" || rand() < 0.3) {
            h.send({ type: "human.message", text: "I can see a fault on the line, so I'm booking an engineer for you." }, actor);
            h.advance(45);
            h.send({ type: "human.run_action", tool: "book_engineer", params: { priority: "standard" } }, actor);
          }
          h.advance(60 + rand() * 240);
          h.send({ type: "session.end", outcome: rand() < 0.88 ? "resolved_by_human" : "escalated_unresolved" }, actor);
        } else if (h.state.session.status !== "completed") {
          h.advance(30);
          h.send({ type: "session.end" });
        }
      }
      rt.register(h.state, { token: `seed-${h.state.session.reference.toLowerCase()}`, workflow, live: false });
    }
  }

  // --- In-flight sessions ---------------------------------------------------
  const marcusUser = humanAgents.find((u) => u.id === "usr_marcus")!;

  // 1. Escalated to L2, waiting in queue (mirrors the product reference).
  const waiting = new SimulationHarness(
    { workflow, policy, agent },
    { id: "ses_a12467", reference: "VA-12467", tenantId: workflow.tenantId, scenario: "wan_down", channel: "sms", customerLabel: "Account ••4127", startAt: now - 7 * 60_000 },
  );
  waiting.runCustomer({ issue: "My internet isn't working. The router lights look different." });
  rt.register(waiting.state, { token: "demo-escalated", workflow, live: true });

  // 2. AI active, waiting for a closer view after glare.
  const glare = new SimulationHarness(
    { workflow, policy, agent },
    { id: "ses_a12468", reference: "VA-12468", tenantId: workflow.tenantId, scenario: "glare_then_clear", channel: "secure_link", customerLabel: "Account ••8830", startAt: now - 2.5 * 60_000 },
  );
  glare.runCustomer({ maxTurns: 4 });
  rt.register(glare.state, { token: "demo-glare", workflow, live: true });

  // 3. Human active after unclear evidence.
  const human = new SimulationHarness(
    { workflow, policy, agent },
    { id: "ses_a12465", reference: "VA-12465", tenantId: workflow.tenantId, scenario: "persistently_unclear", channel: "contact_centre", customerLabel: "Account ••2291", startAt: now - 11 * 60_000 },
  );
  human.runCustomer();
  const marcus = { type: "human_agent" as const, id: marcusUser.id, name: marcusUser.name };
  human.advance(40);
  human.send({ type: "human.join" }, marcus);
  human.send({ type: "human.take_over" }, marcus);
  human.send({ type: "human.note", text: "Strong window glare. Asking customer to close blind." }, marcus);
  rt.register(human.state, { token: "demo-human", workflow, live: true });

  // 4. AI guiding a power cycle.
  const cycling = new SimulationHarness(
    { workflow, policy, agent },
    { id: "ses_a12469", reference: "VA-12469", tenantId: workflow.tenantId, scenario: "power_cycle_fix", channel: "qr", customerLabel: "Account ••5519", startAt: now - 4 * 60_000 },
  );
  cycling.runCustomer({ maxTurns: 5 });
  rt.register(cycling.state, { token: "demo-power-cycle", workflow, live: true });
}
